mapper.select:
SELECT IFNULL(SUM(oi.quantity), 0)
FROM `order` o
JOIN order_item oi ON oi.order_id = o.id
WHERE o.user_id = #{userId}
  AND o.seckill_apply_id = #{applyId}
  AND o.status IN (0, 1, 2, 3)

SELECT o.* FROM `order` o WHERE EXISTS ( SELECT 1 FROM order_item oi INNER JOIN product p ON p.id = oi.product_id WHERE oi.order_id = o.id AND p.merchant_id = #{merchantId} AND p.deleted = 0 ) AND NOT EXISTS ( SELECT 1 FROM order_item oi LEFT JOIN product p ON p.id = oi.product_id WHERE oi.order_id = o.id AND (p.id IS NULL OR p.merchant_id != #{merchantId} OR p.deleted != 0) )
AND o.status = #{status}
ORDER BY o.create_time DESC, o.id DESC
